WITH lines AS (SELECT id, customer_id, created_at, coupon_codes, key, value FROM carts LATERAL VIEW OUTER EXPLODE(attributes) x AS key, value), exploded AS (SELECT id, created_at, key, value_2 FROM lines LATERAL VIEW EXPLODE(coupon_codes) x AS value_2), cleaned AS (SELECT *, DATE_FORMAT(created_at, 'yyyy-MM-dd') AS created_at_label, COALESCE(value_2, 'UNKNOWN') AS value_2_clean FROM exploded WHERE TO_DATE(created_at) >= '2025-09-01'), filtered AS (SELECT id, created_at, key, created_at_label, value_2_clean, TRIM(key) AS clean_key FROM cleaned WHERE value_2 IS NOT NULL), cleaned_carts AS (SELECT id, created_at, key, created_at_label, value_2_clean, clean_key, UPPER(key) AS key_upper, DATE_FORMAT(created_at, 'yyyy-MM-dd') AS created_at_label_2, COALESCE(key, 'OTHER') AS key_filled FROM filtered WHERE created_at > DATE '2025-03-01' AND key IS NOT NULL) SELECT key, MAX(created_at) AS last_created_at, COUNT(DISTINCT id) AS distinct_ids, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes_2, COUNT(CASE WHEN key = 'gift' THEN 1 END) AS gift_count, COUNT(*) FILTER (WHERE key = 'gift') AS gift_rows FROM cleaned_carts GROUP BY key ORDER BY span_minutes DESC;
